/* Backend content is untrusted: every text leaf is escaped; raw HTML is never interpreted. */
(() => {
  "use strict";
  const escape = (value) => String(value ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const text = (vi, en) => document.documentElement.lang === "en" ? en : vi;
  function inline(value) {
    // Keep escaped user text separate from markup generated by the renderer.
    const parts = String(value).split(/(`[^`\n]+`|\[[^\]\n]+\]\([^\s)]+\))/g);
    return parts.map((part) => {
      if (part.startsWith("`") && part.endsWith("`")) return `<code>${escape(part.slice(1, -1))}</code>`;
      const link = part.match(/^\[([^\]]+)\]\(([^)]+)\)$/);
      if (link) {
        try { const url = new URL(link[2]); if (["https:", "http:"].includes(url.protocol)) return `<a href="${escape(url.href)}" target="_blank" rel="noopener noreferrer">${escape(link[1])} ↗</a>`; } catch { /* Render unsupported links as text. */ }
        return escape(part);
      }
      return escape(part).replace(/\*\*([^*\n]+)\*\*/g, "<strong>$1</strong>").replace(/\*([^*\n]+)\*/g, "<em>$1</em>");
    }).join("");
  }
  function markdown(source, depth = 0) {
    if (depth > 16) return `<pre>${escape(source)}</pre>`;
    const lines = String(source).replace(/\r\n?/g, "\n").split("\n"), out = [];
    let index = 0;
    const cells = (line) => line.trim().replace(/^\|/, "").replace(/\|$/, "").split("|").map((cell) => cell.trim());
    while (index < lines.length) {
      const line = lines[index];
      if (!line.trim()) { index++; continue; }
      const fence = line.match(/^\s*(`{3,}|~{3,})([\w+-]*)\s*$/);
      if (fence) {
        const code = []; index++;
        while (index < lines.length && !new RegExp(`^\\s*${fence[1][0]}{${fence[1].length},}\\s*$`).test(lines[index])) code.push(lines[index++]);
        if (index < lines.length) index++;
        out.push(`<div class="code-block"><div class="code-language">${escape(fence[2] || text("Mã", "Code"))}</div><pre><code>${escape(code.join("\n"))}</code></pre></div>`); continue;
      }
      const heading = line.match(/^(#{1,6})\s+(.+)$/);
      if (heading) { out.push(`<h${heading[1].length}>${inline(heading[2])}</h${heading[1].length}>`); index++; continue; }
      if (/^\s*(---+|\*\*\*+|___+)\s*$/.test(line)) { out.push("<hr>"); index++; continue; }
      if (index + 1 < lines.length && line.includes("|") && /^\s*\|?\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)+\|?\s*$/.test(lines[index + 1])) {
        const headers = cells(line), rows = []; index += 2;
        while (index < lines.length && lines[index].includes("|") && lines[index].trim()) rows.push(cells(lines[index++]));
        out.push(`<div class="markdown-table"><table><thead><tr>${headers.map((cell) => `<th>${inline(cell)}</th>`).join("")}</tr></thead><tbody>${rows.map((row) => `<tr>${headers.map((_, i) => `<td>${inline(row[i] || "")}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`); continue;
      }
      if (/^\s*>/.test(line)) {
        const quote = []; while (index < lines.length && /^\s*>/.test(lines[index])) quote.push(lines[index++].replace(/^\s*>\s?/, ""));
        out.push(`<blockquote>${markdown(quote.join("\n"), depth + 1)}</blockquote>`); continue;
      }
      if (/^\s*([-+*]|\d+[.)])\s+/.test(line)) {
        const ordered = /^\s*\d+[.)]/.test(line), items = [];
        while (index < lines.length && (ordered ? /^\s*\d+[.)]\s+/.test(lines[index]) : /^\s*[-+*]\s+/.test(lines[index]))) items.push(lines[index++].replace(/^\s*([-+*]|\d+[.)])\s+/, ""));
        out.push(`<${ordered ? "ol" : "ul"}>${items.map((item) => `<li>${inline(item)}</li>`).join("")}</${ordered ? "ol" : "ul"}>`); continue;
      }
      const paragraph = [line]; index++;
      while (index < lines.length && lines[index].trim() && !/^\s*(#{1,6}\s|>|`{3,}|~{3,}|[-+*]\s|\d+[.)]\s)/.test(lines[index]) && !(lines[index].includes("|") && /^\s*\|?\s*:?-{3,}/.test(lines[index + 1] || ""))) paragraph.push(lines[index++]);
      out.push(`<p>${paragraph.map(inline).join("<br>")}</p>`);
    }
    return `<article class="markdown-body">${out.join("")}</article>`;
  }
  function json(value, prefix) {
    let remaining = 2500;
    function node(item, path, depth, key = null) {
      if (--remaining < 0) return `<div class="viewer-limit">${text("Cây thu gọn để giữ giao diện mượt; xem Nguồn để đọc toàn bộ.", "Tree limited for responsiveness; use Source to read the full content.")}</div>`;
      const label = key === null ? "" : `<span class="json-key">${escape(key)}</span><span class="json-colon">: </span>`;
      if (item !== null && typeof item === "object") {
        const entries = Object.entries(item), array = Array.isArray(item);
        if (!entries.length) return `<div class="json-leaf">${label}<span class="json-punctuation">${array ? "[]" : "{}"}</span></div>`;
        if (depth > 12) return `<div class="json-leaf">${label}<span class="viewer-limit">${text("Xem nguồn cho nội dung sâu hơn", "Use Source for deeper content")}</span></div>`;
        const children = [];
        for (const [name, child] of entries) {
          if (remaining <= 0) { children.push(`<div class="viewer-limit">${text("Còn nội dung trong Nguồn.", "More content is available in Source.")}</div>`); break; }
          children.push(node(child, `${path}/${encodeURIComponent(name)}`, depth + 1, name));
        }
        return `<details class="json-branch" data-json-path="${escape(`${prefix}:${path}`)}" ${depth < 1 ? "open" : ""}><summary>${label}<span class="json-punctuation">${array ? "[ ]" : "{ }"}</span><span class="json-count">${entries.length} ${array ? text("phần tử", "items") : text("trường", "fields")}</span></summary><div class="json-children">${children.join("")}</div></details>`;
      }
      const type = item === null ? "null" : typeof item;
      return `<div class="json-leaf">${label}<span class="json-${type}">${escape(typeof item === "string" ? JSON.stringify(item) : String(item))}</span></div>`;
    }
    return `<div class="json-tree">${node(value, "$", 0)}</div>`;
  }
  window.CoreInspectViewers = { markdown, json, escape };
})();
